where c.codigo = 'codigos_postales_de_sepomex'
  and not exists (
    select 1 from catalogo_valor cv
    where cv.catalogo_id = c.id and cv.clave = v.clave and cv.vigente_hasta is null
  );

-- Última parte: marca el catálogo como cargado y comprueba la cuenta.
update catalogo_sat
   set version = greatest(version, 1), actualizado_en = coalesce(actualizado_en, now()),
       notas = 'Catálogo SEPOMEX cargado por partes desde el SQL Editor.'
 where codigo = 'codigos_postales_de_sepomex';

do $$
declare v_n int;
begin
  select valores_vigentes into v_n from v_catalogos_estado where codigo = 'codigos_postales_de_sepomex';
  if v_n <> 32353 then
    raise exception 'Quedaron % códigos postales de 32353: falta correr alguna parte', v_n;
  end if;
  if not public.clave_valida_en_catalogo('codigos_postales_de_sepomex', '01000') then
    raise exception 'El 01000 perdió el cero de la izquierda';
  end if;
  raise notice 'OK · % códigos postales cargados', v_n;
end $$;

-- La API de gestión no devuelve los RAISE NOTICE, así que esta última parte se
-- veía como un `[]` indistinguible de "no hizo nada". El bloque de arriba
-- revienta si la cuenta no cuadra, así que ver la tabla ya significa que pasó.
select 'códigos postales' as bundle,
       (select valores_vigentes from v_catalogos_estado where codigo = 'codigos_postales_de_sepomex')::text
         || ' cargados' as estado,
       (select descripcion from v_catalogo_vigente
         where catalogo = 'codigos_postales_de_sepomex' and clave = '01000') as prueba_cero_a_la_izquierda;
